function register_failed_attempt(): void
{
    $now = time();
    $remote = $_SERVER['REMOTE_ADDR'] ?? '';
    if (!is_string($remote) || filter_var($remote, FILTER_VALIDATE_IP) === false) {
        $remote = 'unknown';
    }
    $store_dir = CRED_DIR . '/.nc-attempts';
    if (!is_dir($store_dir)) {
        @mkdir($store_dir, 0700, true);
    }
    if (is_dir($store_dir)) {
        $store = $store_dir . '/' . $remote . '.json';
        $remote_attempts = [];
        if (is_file($store)) {
            $remote_attempts = json_decode((string)file_get_contents($store), true);
            $remote_attempts = is_array($remote_attempts) ? $remote_attempts : [];
        }
        $remote_attempts = array_values(array_filter($remote_attempts, static fn($t): bool => is_int($t) && ($now - $t) < NC_ATTEMPT_WINDOW));
        $remote_attempts[] = $now;
        if (count($remote_attempts) > NC_MAX_ATTEMPTS) {
            json_err('Too many failed attempts, wait 10 minutes and retry', 429);
        }
        $tmp = $store . '.' . bin2hex(random_bytes(6));
        if (@file_put_contents($tmp, json_encode($remote_attempts), LOCK_EX) !== false) {
            @rename($tmp, $store);
        }
    }
    $attempts = is_array($_SESSION['nc_attempts'] ?? null) ? $_SESSION['nc_attempts'] : [];
    $attempts = array_values(array_filter($attempts, static fn($t): bool => is_int($t) && ($now - $t) < NC_ATTEMPT_WINDOW));
    $attempts[] = $now;
    $_SESSION['nc_attempts'] = $attempts;
    if (count($attempts) > NC_MAX_ATTEMPTS) {
        json_err('Too many failed attempts, wait 10 minutes and retry', 429);
    }
}

function clear_failed_attempts(): void
{
    unset($_SESSION['nc_attempts']);
    $remote = $_SERVER['REMOTE_ADDR'] ?? '';
    if (!is_string($remote) || filter_var($remote, FILTER_VALIDATE_IP) === false) {
        $remote = 'unknown';
    }
    $store = CRED_DIR . '/.nc-attempts/' . $remote . '.json';
    if (is_file($store)) {
        @unlink($store);
    }
}

